"""Etape practice care reunesc tehnologiile în site-ul de referință."""
from course_model import *

c=chapter('project','Proiectul complet · Sweet Corner','Construiește paginile, produsele și interacțiunile, apoi verifică tot site-ul.','Exemplul profesoarei: index.js, views, resurse și schema SQL; adaptare cu identificatori în engleză','flag')

def H(id,title,idea,code,tests):
 lesson(c,id,title,idea,code,idea,q('Ce construiești în această etapă?',title,'Un fișier fără legătură cu proiectul','Doar modifici browserul'),html('Construiește fragmentul următor pornind de la cerințele testelor. '+idea,code,tests))

H('project-shell','Structura paginii','Folosește header, nav, main și footer. Titlul principal este Sweet Corner, iar meniul are legături către / și /products.', '<header><h1>Sweet Corner</h1><nav aria-label="Main"><a href="/">Home</a><a href="/products">Products</a></nav></header><main><h2>Fresh every day</h2></main><footer>Sweet Corner</footer>',[exact('header h1','Sweet Corner'),attr('nav','aria-label','Main'),attr('nav a:nth-child(2)','href','/products'),count('main h2'),count('footer')])
H('project-menu','Meniu cu submeniu','O listă imbricată grupează categoriile. Butonul pentru mobil are aria-expanded=false și aria-controls=main-menu. CSS și JavaScript îi vor modifica starea.', '<button id="menu-toggle" aria-expanded="false" aria-controls="main-menu">Menu</button><nav id="main-menu"><ul><li><a href="/products">Products</a><ul><li><a href="/products?type=cake">Cakes</a></li><li><a href="/products?type=pastry">Pastries</a></li></ul></li></ul></nav>',[attr('#menu-toggle','aria-controls','main-menu'),attr('#menu-toggle','aria-expanded','false'),count('#main-menu ul ul a',2)])
H('project-gallery','Galerie statică','Fiecare imagine are un text alternativ și o legendă. Folosește figure și figcaption, în containerul .gallery. În site-ul complet datele vin din gallery.json.', '<section class="gallery"><figure><img src="/assets/images/cake.svg" alt="Chocolate cake"><figcaption>Chocolate cake</figcaption></figure><figure><img src="/assets/images/tea.svg" alt="Fruit pastry"><figcaption>Fruit pastry</figcaption></figure></section>',[count('.gallery figure',2),attr('img','alt','Chocolate cake'),exact('figcaption','Chocolate cake')])
H('project-picture','Imagini responsive','picture oferă o sursă alternativă la maximum 600px și un img de rezervă. În proiect sharp generează fișiere WebP din imaginile sursă.', '<picture><source media="(max-width: 600px)" srcset="/assets/images/cake-small.webp"><img src="/assets/images/cake.webp" alt="Chocolate cake" loading="lazy"></picture>',[attr('picture source','media','(max-width: 600px)'),attr('picture img','loading','lazy'),attr('picture img','alt','Chocolate cake')])
H('project-video','Video și subtitrări','video are controls și poster; source declară video/mp4, iar track indică subtitrările în engleză. Fișierul VTT începe cu WEBVTT și conține intervale de timp.', '<video controls poster="/assets/images/cake.svg"><source src="/assets/media/bakery.mp4" type="video/mp4"><track kind="subtitles" srclang="en" label="English" src="/assets/media/captions.vtt" default></video>',[count('video[controls]'),attr('video source','type','video/mp4'),attr('track','kind','subtitles'),attr('track','srclang','en')])
H('project-faq','Întrebări frecvente','details și summary oferă întrebări care se deschid fără JavaScript. Scrie două întrebări: Delivery? și Ingredients?.', '<section id="faq"><h2>FAQ</h2><details><summary>Delivery?</summary><p>Collect your order at our bakery.</p></details><details><summary>Ingredients?</summary><p>See the product page for allergens.</p></details></section>',[count('#faq details',2),exact('summary','Delivery?'),exact('details:last-child summary','Ingredients?')])
H('project-table','Tabel și orar','Tabelul de program are caption, thead și tbody. th cu scope=col identifică antetele Day și Hours; o celulă poate uni două rânduri prin rowspan.', '<table><caption>Opening hours</caption><thead><tr><th scope="col">Day</th><th scope="col">Hours</th></tr></thead><tbody><tr><td>Monday</td><td rowspan="2">09:00–18:00</td></tr><tr><td>Tuesday</td></tr></tbody></table>',[exact('caption','Opening hours'),count('thead th[scope="col"]',2),attr('tbody td[rowspan]','rowspan','2')])

lesson(c,'project-grid','Așază galeria pe ecrane diferite','Galeria are trei coloane pe desktop și una sub 600px. minmax(0,1fr) permite micșorarea conținutului fără depășirea paginii.', '.gallery { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 20px; }\n@media (max-width: 600px) { .gallery { grid-template-columns: 1fr; } }','Testează ambele lățimi; faptul că arată bine pe desktop nu verifică și mobilul.',q('Ce verificăm pentru layout?','Atât desktop, cât și mobil','Doar culoarea cardurilor','Doar existența unui fișier CSS'),css('Galeria trebuie să aibă trei coloane la 900px și una la 480px.', '.gallery { display:grid; grid-template-columns:repeat(3,minmax(0,1fr)); gap:20px; } @media(max-width:600px){.gallery{grid-template-columns:1fr;}}','<div class="gallery"><div>Cake</div><div>Pastry</div><div>Ice cream</div></div>',[cols('.gallery',3,900),cols('.gallery',1,480)]))

lesson(c,'project-menu-action','Deschide meniul mobil','Butonul schimbă aria-expanded și proprietatea hidden a meniului. Aceeași stare trebuie reflectată vizual și pentru cititoarele de ecran.', 'const button = document.querySelector("#menu-toggle");\nconst menu = document.querySelector("#main-menu");\nbutton.addEventListener("click", () => {\n  const expanded = button.getAttribute("aria-expanded") === "true";\n  button.setAttribute("aria-expanded", String(!expanded));\n  menu.hidden = expanded;\n});','Clicul din test trebuie să deschidă meniul.',q('Unde se înregistrează reacția la clic?','În addEventListener','În PostgreSQL','În caption'),dom('La clic, schimbă aria-expanded în true și afișează meniul.', 'const button = document.querySelector("#menu-toggle"); const menu = document.querySelector("#main-menu"); button.addEventListener("click", () => { const expanded = button.getAttribute("aria-expanded") === "true"; button.setAttribute("aria-expanded", String(!expanded)); menu.hidden = expanded; });','<button id="menu-toggle" aria-expanded="false">Menu</button><nav id="main-menu" hidden>Products</nav>',[attr('#menu-toggle','aria-expanded','true'),absent('#main-menu[hidden]')],[dict(type='click',selector='#menu-toggle')]))

lesson(c,'project-filter','Filtre combinate pentru produse','Mai multe filtre se aplică împreună: textul din nume, categoria și prețul maxim. Categoria all nu restrânge rezultatele.', 'products.filter(product => product.name.toLowerCase().includes(search.toLowerCase()) && (category === "all" || product.category === category) && product.price <= maxPrice);','Toate condițiile folosesc AND. Testează și lista fără rezultate.',q('Cum combinăm cerințele care trebuie îndeplinite simultan?','Cu &&','Cu +','Cu OR obligatoriu'),js('Primești {products, search, category, maxPrice}. Returnează id-urile produselor potrivite, în ordinea inițială.','function solve(input) { return input.products.filter(product => product.name.toLowerCase().includes(input.search.toLowerCase()) && (input.category === "all" || product.category === input.category) && product.price <= input.maxPrice).map(product => product.id); }',[({'products':[{'id':1,'name':'Cake','category':'cake','price':12},{'id':2,'name':'Tea','category':'drink','price':4}],'search':'CA','category':'all','maxPrice':15},[1]),({'products':[],'search':'','category':'all','maxPrice':100},[])]))

lesson(c,'project-sort','Sortare cu criteriu secundar','Prețurile egale se ordonează după nume. Copiază vectorul înainte de sortare ca să păstrezi datele originale.', '[...products].sort((a, b) => a.price - b.price || a.name.localeCompare(b.name));','Comparatorul întoarce o valoare negativă, zero sau pozitivă.',q('De ce folosim [...products]?','Pentru a sorta o copie','Ca să ștergem produsele','Ca să modificăm baza de date'),js('Returnează numele ordonate crescător după price și apoi după name.','function solve(input) { return [...input].sort((a,b) => a.price-b.price || a.name.localeCompare(b.name)).map(product => product.name); }',[([{'name':'Tea','price':4},{'name':'Cake','price':12},{'name':'Bread','price':4}],['Bread','Tea','Cake']),([],[])]))

lesson(c,'project-cart','Coș fără duplicate','Coșul memorează id-uri stabile. Adăugarea aceluiași produs de două ori păstrează o singură apariție. Serializarea pentru localStorage se face separat.', '[...new Set([...cart, productId])]', 'Identitatea produsului nu depinde de poziția lui după sortare.',q('Ce memorăm pentru identitatea unui produs?','Id-ul stabil','Poziția lui temporară','Culoarea cardului'),js('Primești {cart, id}. Returnează coșul cu id adăugat o singură dată.','function solve(input) { return [...new Set([...input.cart,input.id])]; }',[({'cart':['1'],'id':'1'},['1']),({'cart':['1'],'id':'2'},['1','2'])]))

lesson(c,'project-ejs','Carduri EJS din baza de date','Express citește produsele și trimite vectorul către EJS. Template-ul generează carduri cu data-id, data-price și legătura produsului.', '<% for (const product of products) { %>\n<article class="product-card" data-id="<%= product.id %>" data-price="<%= product.price %>"><h2><a href="/product/<%= product.id %>"><%= product.name %></a></h2></article>\n<% } %>','Nu scrie manual câte un card pentru fiecare produs.',q('Cine repetă markup-ul pentru fiecare produs?','Bucla din EJS','CSS grid singur','Favicon-ul'),ejs('Generează câte un card cu titlu și link pentru fiecare produs.', '<% for (const product of products) { %><article class="product-card" data-id="<%= product.id %>" data-price="<%= product.price %>"><h2><a href="/product/<%= product.id %>"><%= product.name %></a></h2></article><% } %>',{'products':[{'id':1,'name':'Cake','price':12},{'id':2,'name':'Pastry','price':6}]},[count('.product-card',2),attr('.product-card','data-id','1'),attr('h2 a','href','/product/1'),exact('h2 a','Cake')]))

lesson(c,'project-route-id','Validează ruta unui produs','O rută primește text în req.params.id. Acceptă doar cifre și un număr întreg sigur, apoi caută produsul. Un id valid dar inexistent produce 404; un id invalid produce 400.', 'app.get("/product/:id", (req, res) => {\n  if (!/^\\d+$/.test(req.params.id)) return res.status(400).send("Invalid id");\n  const product = products.find(item => item.id === Number(req.params.id));\n  if (!product) return res.status(404).send("Not found");\n  res.json(product);\n});','Distinge datele invalide de resursa care nu există.',q('Ce status folosim pentru un produs inexistent cu id valid?','404','200','301'),express('Exportă aplicația: /product/1 întoarce {id:1,name:"Cake"}, id invalid 400, iar alt id 404.','const express = require("express"); const app = express(); const products = [{id:1,name:"Cake"}]; app.get("/product/:id", (req,res) => { if(!/^\\d+$/.test(req.params.id) || !Number.isSafeInteger(Number(req.params.id))) return res.status(400).send("Invalid id"); const product=products.find(item=>item.id===Number(req.params.id)); if(!product)return res.status(404).send("Not found"); res.json(product); }); module.exports=app;',[dict(path='/product/1',json={'id':1,'name':'Cake'}),dict(path='/product/abc',status=400,bodyExpected='Invalid id'),dict(path='/product/99',status=404,bodyExpected='Not found')]))

lesson(c,'project-query','Interogare cu parametri','Clientul pg primește textul SQL și valorile separat. $1 reprezintă primul parametru; nu înlocui manual textul SQL cu șiruri introduse de utilizator.', 'const result = await pool.query("SELECT * FROM products WHERE id = $1", [productId]);\nconst product = result.rows[0];','Dacă rows este gol, produsul nu există. Ruta răspunde 404.',q('Unde trimitem valoarea pentru $1?','În vectorul al doilea argument al query','Într-un selector CSS','În numele template-ului'),text('Scrie interogarea parametrizată pentru produsul cu id-ul cerut.','SELECT * FROM products WHERE id = $1'))
lesson(c,'project-assets','Compilare și imagini generate','La pornire compilăm site.scss în site.css și generăm dimensiuni WebP cu sharp. Sursele rămân separate de fișierele generate.', 'const css = sass.compile(sourceFile).css;\nawait sharp(sourceImage).resize({ width: 480 }).webp().toFile(outputImage);','În proiectul de referință prepareAssets pregătește aceste resurse înainte de a porni aplicația.',q('Ce servește browserului link rel=stylesheet?','CSS-ul generat','Codul SCSS necompilat','Fișierul PostgreSQL'),text('Scrie extensia rezultatului compilării Sass.','.css'))
lesson(c,'project-errors','Erori 400, 404 și 500','Un handler final pentru cereri necunoscute răspunde 404. Handler-ul de erori cu patru parametri răspunde 500. Template-ul afișează mesajul din errors.json.', 'app.use((req, res) => res.status(404).send("Not found"));\napp.use((error, req, res, next) => res.status(500).send("Server error"));','Rutele concrete trebuie înregistrate înaintea fallback-ului.',q('Unde pui fallback-ul 404?','După rutele concrete','Înaintea tuturor rutelor','Într-o regulă CSS'),express('Configurează /broken cu o eroare, handler 500 și fallback 404.','const express = require("express"); const app=express(); app.get("/broken",(req,res,next)=>next(new Error("Training"))); app.use((req,res)=>res.status(404).send("Not found")); app.use((error,req,res,next)=>res.status(500).send("Server error")); module.exports=app;',[dict(path='/missing',status=404,bodyExpected='Not found'),dict(path='/broken',status=500,bodyExpected='Server error')]))
lesson(c,'project-checklist','Verifică site-ul cap-coadă','Deschide Home, Products, un produs și o adresă inexistentă. Verifică meniul mobil, galeria, filtrele, sortarea, coșul, tema, bannerul de preferințe, consola și răspunsurile din Network.', 'GET /           -> 200\nGET /products   -> 200\nGET /product/1  -> 200\nGET /missing    -> 404','Site-ul final se deschide din legătura Proiect complet de pe traseu. Descărcarea surselor îți permite să îl rulezi și separat.',q('Este suficient ca pagina Home să se deschidă?','Nu; verificăm paginile și interacțiunile','Da, întregul proiect e verificat','Da, dacă are dark mode'),text('Ce status aștepți pentru /missing?','404'))
